CREATE TABLE "public"."opportunity_loader" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."opportunity_loader_id_seq") NOT NULL,
  "id_external" text,
  "nombre_del_lead" text,
  "compania" text,
  "contacto_principal" text,
  "compania_del_lead" text,
  "responsable" text,
  "estatus_del_lead" text,
  "embudo_de_ventas" text,
  "presupuesto" text,
  "fecha_de_creacion" text,
  "creado_por" text,
  "ultima_modificacion_el" text,
  "modificado_por" text,
  "etiquetas_del_lead" text,
  "tareas_proximas" text,
  "cerrado_el" text,
  "fecha" text,
  "catastro" text,
  "origen" text,
  "intencion" text,
  "ubicacion" text,
  "tipo" text,
  "domicilio" text,
  "complemento" text,
  "codigo_postal" text,
  "metros" text,
  "reforma" text,
  "objetivo" text,
  "utm_content" text,
  "utm_medium" text,
  "utm_campaign" text,
  "utm_source" text,
  "utm_term" text,
  "utm_referrer" text,
  "referrer" text,
  "gclientid" text,
  "gclid" text,
  "fbclid" text,
  "cargo_contacto" text,
  "correo_contacto" text,
  "email_priv_contacto" text,
  "otro_email_contacto" text,
  "telefono_oficina_contacto" text,
  "telefono_oficina_directo_contacto" text,
  "telefono_celular_contacto" text,
  "fax_contacto" text,
  "telefono_de_casa_contacto" text,
  "otro_telefono_contacto" text,
  "terminos_y_condiciones_contacto" text,
  "nota_1" text,
  "nota_2" text,
  "nota_3" text,
  "nota_4" text,
  "nota_5" text,
  "created_at" timestamp without time zone DEFAULT now(),
  "updated_at" timestamp without time zone,
  "deleted_at" timestamp without time zone,
  "created_by" text DEFAULT public.crm_current_profile_id()::text,
  "updated_by" text,
  "deleted_by" text,
  CONSTRAINT "opportunity_loader_pkey" PRIMARY KEY ("id")
);

ALTER TABLE "public"."opportunity_loader"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "opportunity_loader_select_by_admin"
  ON "public"."opportunity_loader"
  FOR SELECT
  TO "authenticated"
  USING (
    (SELECT public.crm_current_role()) = 'admin'::text
  );

CREATE POLICY "opportunity_loader_insert_by_admin"
  ON "public"."opportunity_loader"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (
    (SELECT public.crm_current_role()) = 'admin'::text
  );

REVOKE ALL
  ON TABLE "public"."opportunity_loader"
  FROM "anon", "authenticated";

GRANT INSERT, SELECT
  ON TABLE "public"."opportunity_loader"
  TO "authenticated";

GRANT ALL
  ON TABLE "public"."opportunity_loader"
  TO "postgres", "service_role";